#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite); library(ggplot2)})
`%||%` <- function(a,b) if (is.null(a)||length(a)==0||is.na(a[1])) b else a
o <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--input2',type='character'),make_option('--params',type='character'),make_option('--output',type='character'),make_option('--mantel',type='character'),make_option('--envpoints',type='character'),make_option('--specpoints',type='character'))))
out <- o$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
bad <- function(e,d='',s='Check the input tables and params.json.') { writeLines(toJSON(list(error=e,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); logmsg(paste(e,d)); quit(status=1) }
tryCatch({
 p <- fromJSON(o$params,simplifyVector=FALSE); flat<-unlist(p,recursive=TRUE,use.names=TRUE)
if(length(p)) for(n in names(p)) if(is.list(p[[n]])) p<-c(p,p[[n]])
getp <- function(n,d=NULL,a=character()) { for(z in c(n,a)) { if(!is.null(p[[z]])) return(p[[z]]); if(z%in%names(flat)) return(flat[[z]]) }; d }
yes <- function(x,d=FALSE) { if(is.null(x))return(d); if(is.logical(x))return(isTRUE(x[1])); tolower(as.character(x[1]))%in%c('true','1','yes','on') }
chars <- function(x) if(is.null(x)) character() else trimws(as.character(unlist(x,use.names=FALSE)))
num <- function(x,d) {z<-suppressWarnings(as.numeric(unlist(x))[1]);if(is.na(z))d else z}
tab <- function(f) { if(is.null(f)||!file.exists(f))stop('Table not found: ',f); if(tolower(tools::file_ext(f))=='csv')read.csv(f,check.names=FALSE) else read.delim(f,check.names=FALSE) }
rel <- function(f, base=o$input) { if(is.null(f)||file.exists(f)) f else file.path(dirname(base),f) }
pick <- function(d, aliases, explicit=NULL) { if(!is.null(explicit)&&length(explicit)&&as.character(explicit)[1]%in%names(d))return(as.character(explicit)[1]); z<-names(d)[tolower(names(d))%in%tolower(aliases)];if(!length(z))stop('Missing column: ',paste(aliases,collapse='/'));z[1] }
mode<-tolower(as.character(getp('input_mode','precomputed',c('mode')))[1]); method<-tolower(as.character(getp('correlation_method','pearson'))[1])
if(mode%in%c('precomputed','matrix')) {
 d<-tab(rel(getp('correlation_file',o$input,c('matrix_file')))); labs<-as.character(d[[1]]); mat<-as.matrix(data.frame(lapply(d[-1],function(x)as.numeric(as.character(x))))); colnames(mat)<-names(d)[-1];rownames(mat)<-labs
 if(nrow(mat)!=ncol(mat)||!setequal(rownames(mat),colnames(mat)))stop('Correlation matrix must be square with matching labels.')
 mat<-mat[match(colnames(mat),rownames(mat)),,drop=FALSE];rownames(mat)<-colnames(mat);pv<-matrix(NA_real_,nrow(mat),ncol(mat),dimnames=dimnames(mat));diag(mat)<-1
} else {
 e<-tab(o$input);s<-tab(o$input2%||%getp('spec_table_file',NULL,c('input2_file')));ei<-pick(e,c('id','sample','sample_id','name'),getp('env_id_column',NULL));si<-pick(s,c('id','sample','sample_id','name'),getp('spec_id_column',NULL)); isnum<-function(x){z<-suppressWarnings(as.numeric(as.character(x)));all(is.na(x)|is.finite(z))}; en<-names(e)[vapply(e,isnum,logical(1))];sn<-names(s)[vapply(s,isnum,logical(1))];en<-setdiff(en,ei);sn<-setdiff(sn,si);en<-if(length(chars(getp('features_include'))))intersect(en,chars(getp('features_include')))else setdiff(en,chars(getp('features_exclude')));sn<-if(length(chars(getp('features_include'))))intersect(sn,chars(getp('features_include')))else setdiff(sn,chars(getp('features_exclude')));if(!length(en)||!length(sn))stop('Compute mode requires numeric columns.');e<-as.data.frame(lapply(e[en],as.numeric));s<-as.data.frame(lapply(s[sn],as.numeric));nobs<-min(nrow(e),nrow(s));allx<-cbind(e[seq_len(nobs),,drop=FALSE],s[seq_len(nobs),,drop=FALSE]);mat<-cor(allx,use='pairwise.complete.obs',method=method);pv<-matrix(NA_real_,ncol(mat),ncol(mat),dimnames=dimnames(mat));for(i in seq_len(ncol(mat)))for(j in seq_len(ncol(mat)))if(i!=j){ok<-complete.cases(allx[,c(i,j)]);if(sum(ok)>2)pv[i,j]<-tryCatch(cor.test(allx[ok,i],allx[ok,j],method=method,exact=FALSE)$p.value,error=function(x)NA_real_)};diag(pv)<-0
}
features<-rownames(mat);inc<-chars(getp('features_include'));exc<-chars(getp('features_exclude'));if(length(inc))features<-intersect(features,inc);features<-setdiff(features,exc);ord<-chars(getp('feature_order'));if(length(ord))features<-c(intersect(ord,features),setdiff(features,ord));mat<-mat[features,features,drop=FALSE];pv<-pv[features,features,drop=FALSE];write.csv(mat,file.path(out,'correlation_matrix_used.csv'));write.csv(data.frame(feature=features),file.path(out,'selected_features.csv'),row.names=FALSE)
read_points<-function(file,side){if(is.null(file)||!file.exists(file))return(data.frame());x<-tab(file);id<-pick(x,c('id','label','name'));y<-if('y'%in%names(x))as.numeric(x$y)else seq_len(nrow(x));xx<-if('x'%in%names(x))as.numeric(x$x)else if(side=='env')rep(-1.5,nrow(x))else rep(length(features)+2.5,nrow(x));key<-as.character(x[[id]]);y[!is.finite(y)]<-seq_len(sum(!is.finite(y)));data.frame(id=key,label=if('label'%in%names(x))as.character(x$label)else key,x=xx,y=y,group=if('group'%in%names(x))as.character(x$group)else side,color=if('color'%in%names(x))as.character(x$color)else NA,side=side,stringsAsFactors=FALSE)}
ep<-read_points(rel(o$envpoints%||%getp('env_points_file')), 'env');sp<-read_points(rel(o$specpoints%||%getp('spec_points_file')),'spec');write.csv(ep,file.path(out,'env_points_used.csv'),row.names=FALSE);write.csv(sp,file.path(out,'spec_points_used.csv'),row.names=FALSE)
mf<-rel(o$mantel%||%getp('mantel_file'));m<-if(!is.null(mf)&&file.exists(mf))tab(mf)else data.frame();if(nrow(m)){ec<-pick(m,c('env','environment','env_var'),getp('env_column'));sc<-pick(m,c('spec','species','spec_var'),getp('spec_column'));rc<-pick(m,c('r','mantel_r','correlation'),getp('r_column'));pc<-pick(m,c('p','pvalue','p_value','p.value'),getp('pvalue_column'));m$env<-as.character(m[[ec]]);m$spec<-as.character(m[[sc]]);m$r<-as.numeric(m[[rc]]);m$p<-as.numeric(m[[pc]])}else m<-data.frame(env=character(),spec=character(),r=numeric(),p=numeric());m<-m[m$env%in%features&m$spec%in%features,,drop=FALSE];m$pbin<-cut(m$p,breaks=c(-Inf,as.numeric(unlist(getp('p_bins',c(.001,.01,.05,.1)))),Inf),labels=FALSE);m$ex<-ep$x[match(m$env,ep$id)];m$ey<-ep$y[match(m$env,ep$id)];m$sx<-sp$x[match(m$spec,sp$id)];m$sy<-sp$y[match(m$spec,sp$id)];write.csv(m,file.path(out,'mantel_results.csv'),row.names=FALSE);sel<-chars(getp('selected_links'));chosen<-if(length(sel))m[seq_len(nrow(m))%in%as.integer(sel)|m$env%in%sel|m$spec%in%sel,,drop=FALSE]else m[FALSE,,drop=FALSE];write.csv(chosen,file.path(out,'selected_links.csv'),row.names=FALSE)
cells<-expand.grid(x=seq_along(features),y=seq_along(features));cells$r<-as.vector(mat);cells$fx<-features[cells$x];cells$fy<-features[cells$y];tri<-tolower(as.character(getp('triangle_mode','mixed'))[1]);cells$show<-cells$y==cells$x|(cells$y>cells$x&tri%in%c('both','lower','mixed'))|(cells$y<cells$x&tri%in%c('both','upper','mixed'));cells<-cells[cells$show,,drop=FALSE]
g<-ggplot(cells,aes(x=x,y=y,fill=r))+geom_tile(colour=as.character(getp('cell_border_color','#555555'))[1],linewidth=num(getp('cell_border_width',.25),.25),alpha=num(getp('cell_alpha',1),1))+scale_fill_gradient2(low=as.character(getp('low_color','#3B4CC0'))[1],mid=as.character(getp('mid_color','#F7F7F7'))[1],high=as.character(getp('high_color','#B40426'))[1],limits=as.numeric(unlist(getp('color_limits',c(-1,1)))),name=as.character(getp('colorbar_title','Pearson r'))[1])+scale_x_continuous(breaks=seq_along(features),labels=features)+scale_y_continuous(breaks=seq_along(features),labels=rev(features))+coord_cartesian(xlim=c(if(nrow(ep))-2 else 0,length(features)+if(nrow(sp))3 else length(features)+1),ylim=c(length(features)+.5,-.5),clip='off')+theme_minimal(base_size=num(getp('base_size',11),11))+theme(panel.grid=element_blank(),legend.position=if(yes(getp('legend_show',TRUE)))as.character(getp('legend_position','right'))[1]else'none')
if(nrow(m))for(i in seq_len(nrow(m))){t<-seq(0,1,length.out=40);xx<-(1-t)^3*m$ex[i]+3*(1-t)^2*t*(m$ex[i]+.3)+3*(1-t)*t^2*(m$sx[i]-.3)+t^3*m$sx[i];yy<-(1-t)^3*m$ey[i]+3*(1-t)^2*t*m$ey[i]+3*(1-t)*t^2*m$sy[i]+t^3*m$sy[i];g<-g+geom_path(data=data.frame(x=xx,y=yy),aes(x,y),inherit.aes=FALSE,colour='#8C2D69',alpha=num(getp('link_alpha',.65),.65),linewidth=num(getp('link_width_max',4),4)*abs(m$r[i])/max(1,max(abs(m$r))))}
if(nrow(ep)&&yes(getp('env_point_show',TRUE)))g<-g+geom_point(data=ep,aes(x,y),inherit.aes=FALSE,shape=21,fill=as.character(getp('env_point_color','#4477AA'))[1],size=num(getp('env_point_size',4),4));if(nrow(sp)&&yes(getp('spec_point_show',TRUE)))g<-g+geom_point(data=sp,aes(x,y),inherit.aes=FALSE,shape=21,fill=as.character(getp('spec_point_color','#EE6677'))[1],size=num(getp('spec_point_size',4),4));ggsave(file.path(out,'result.svg'),g,width=num(getp('width',12),12),height=num(getp('height',9),9));ggsave(file.path(out,'result.pdf'),g,width=num(getp('width',12),12),height=num(getp('height',9),9));ggsave(file.path(out,'result.png'),g,width=num(getp('width',12),12),height=num(getp('height',9),9),dpi=num(getp('dpi',300),300))
if(requireNamespace('plotly',quietly=TRUE)){pl<-plotly::plot_ly();for(i in seq_len(nrow(cells)))pl<-plotly::add_trace(pl,type='scatter',mode='markers',x=cells$x[i],y=cells$y[i],marker=list(size=25,color=cells$r[i],colorscale='RdBu',cmin=-1,cmax=1),text=paste(cells$fx[i],cells$fy[i],cells$r[i],sep='<br>'),hoverinfo='text',showlegend=FALSE);for(i in seq_len(nrow(ep)))pl<-plotly::add_trace(pl,type='scatter',mode='markers',x=ep$x[i],y=ep$y[i],text=ep$label[i],hoverinfo='text',name='Environment');for(i in seq_len(nrow(sp)))pl<-plotly::add_trace(pl,type='scatter',mode='markers',x=sp$x[i],y=sp$y[i],text=sp$label[i],hoverinfo='text',name='Species');pl<-plotly::layout(pl,title=as.character(getp('title','Mantel Correlation Network'))[1],yaxis=list(autorange='reversed'));htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE)}else writeLines('<html><body>Plotly unavailable</body></html>',file.path(out,'result.html'))
fig<-list(plugin='interactive_mantel_correlation_network',input_mode=mode,n_features=length(features),n_links=nrow(m),outputs=list('result.svg','result.pdf','result.png','result.html','figure.json','run.log','correlation_matrix_used.csv','mantel_results.csv','env_points_used.csv','spec_points_used.csv','selected_links.csv'));writeLines(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json'));if(file.exists(file.path(out,'error.json')))unlink(file.path(out,'error.json'));logmsg('Completed render.')
},error=function(e)bad('Mantel correlation network rendering failed',conditionMessage(e)))
